using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1️⃣  Strongly-typed retrieval — returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip using the typed metadata:
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person? deserialized = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {deserialized}");

// 2️⃣  Probe without throwing — TryGetTypeInfo returns false when
//     metadata isn't available instead of throwing.
//     Here we use an empty resolver so nothing is resolvable.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => { if (ti.Type == typeof(Secret)) throw new NotSupportedException(); } }
    }
};

// Person resolves fine:
if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"\n✔ Metadata available for Person: {info!.Type.Name}");
else
    Console.WriteLine("\n✘ No metadata for Person");

// Secret does NOT resolve (modifier throws), so TryGetTypeInfo returns false:
if (limited.TryGetTypeInfo(typeof(Secret), out _))
    Console.WriteLine("✔ Metadata available for Secret");
else
    Console.WriteLine("✘ No metadata for Secret — and no exception was thrown!");

// Types used in the demo:
public record Person(string Name, int Age);
public record Secret(string Value);

