Console.WriteLine($"Serialized: {json}");

Person? deserialized = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {deserialized}");

// 2️⃣  Probe without throwing — TryGetTypeInfo returns false when the
//     resolver cannot provide metadata (returns null) for a given type.
//     We use a selective resolver that only handles Person.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new SelectiveResolver()
};

// Person resolves fine:
if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"\n✔ Metadata available for Person: {info!.Type.Name}");
else
    Console.WriteLine("\n✘ No metadata for Person");

// Secret is NOT supported by our selective resolver → TryGetTypeInfo returns false.
if (limited.TryGetTypeInfo(typeof(Secret), out _))
    Console.WriteLine("✔ Metadata available for Secret");
else
    Console.WriteLine("✘ No metadata for Secret — no exception thrown!");

// ---------- types & helpers ----------

public record Person(string Name, int Age);
public record Secret(string Value);

/// A resolver that only provides metadata for Person, returning null for anything else.
file class SelectiveResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);

        return null; // signals "I don't know this type"
    }
}
